toolCalls.args:
{"command": "cd /tmp/sv-4a3cc82c66d34b579a73c0816429bbfe
# Use nm or objdump to find what's at those addresses for SGen worker
llvm-addr2line-18 -f -e libmonosgen-2.0.so.dbg --obj=libmonosgen-2.0.so 0x2f4b20 0x2f4c84 2>/dev/null
echo "---"
# Try using the symbol table to find nearest function
aarch64-linux-gnu-nm -C libmonosgen-2.0.so.dbg 2>/dev/null | sort | awk -v addr1="2f4b20" -v addr2="2f4c84" '
  { if ($1 <= addr1) f1=$3" ("$1")"; if ($1 <= addr2) f2=$3" ("$1")" }
  END { print "0x2f4b20 -> " f1; print "0x2f4c84 -> " f2 }
' 2>/dev/null || echo "nm approach failed"", "description": "Find SGen worker function names via symbol table", "initial_wait": 30}

arguments.command:
cd /tmp/sv-4a3cc82c66d34b579a73c0816429bbfe
# Use dynamic symbols and readelf to find nearest function
aarch64-linux-gnu-objdump -t libmonosgen-2.0.so.dbg 2>/dev/null | awk '$1 ~ /^[0-9a-f]+$/ && ($3 == "F" || $4 == "F") { addr=strtonum("0x"$1); size=strtonum("0x"$5); print addr, addr+size, $NF }' | sort -n | awk '
  BEGIN { t1=0x2f4b20; t2=0x2f4c84 }
  { if ($1 <= t1 && $2 > t1) print "0x2f4b20 -> "$3" (+"sprintf("0x%x",t1-$1)")"; 
    if ($1 <= t2 && $2 > t2) print "0x2f4c84 -> "$3" (+"sprintf("0x%x",t2-$1)")" }
' 2>/dev/null | head -10

